KG42.register("rules-f8a98f04dea681344c114c57",{"id":"42-data_center_space_time_flexibility::v141-c-R012","paper":"42-data_center_space_time_flexibility","record":{"rule_id":"v141-c-R012","mechanism_id":"v141-a-M03","name":"Market payment","process_stage":"settlement","market_meaning":"The consumer's load charge uses the hub price, while its virtual-link service is remunerated by the hub-minus-alternative-node price difference multiplied by shifted load. Scope: Hub-based virtual-link market for a flexible consumer offering alternative delivery nodes.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["settlement.payment"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Hub-based virtual-link market for a flexible consumer offering alternative delivery nodes.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e024"]},"x":[{"variable_id":"v141-c-R012-x-d","symbol":"d","meaning":"Cleared load requested by the flexible consumer at its hub node in the hub-based virtual-link formulation.","kind":"operational","domain":"0 \\le d \\le \\bar d","unit":null,"indices":[],"evidence_ids":["v141-b-g02-e020","v141-b-g02-e024"]},{"variable_id":"v141-c-R012-x-delta","symbol":"\\delta_{n_h,n}","meaning":"Cleared amount of load shifted from hub node n_h to alternate delivery node n via a virtual link.","kind":"operational","domain":"\\delta_{n_h,n} \\ge 0","unit":null,"indices":["n_h (hub node)","n \\in N_d"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020","v141-b-g02-e024"]}],"theta":[{"parameter_id":"v141-c-R012-theta-alpha-d","symbol":"\\alpha^d","meaning":"Bid price submitted by the flexible consumer for requested load at its hub node.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e024"]},{"parameter_id":"v141-c-R012-theta-pi","symbol":"\\pi_n","meaning":"Cleared nodal price (LMP) at node n; the settlement expression uses the hub-node value \\pi_{n_h} and alternate-node values \\pi_n.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n \\in N"],"evidence_ids":["v141-b-g02-e020","v141-b-g02-e024"]},{"parameter_id":"v141-c-R012-theta-dbar","symbol":"\\bar d","meaning":"Maximum requested-load quantity submitted by the flexible consumer at its hub node; upper bound on d.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]}],"phi":[{"constraint_id":"v141-c-R012-C001","kind":"procedural","role":"core","statement":"The consumer's load charge uses the hub price, while its virtual-link service is remunerated by the hub-minus-alternative-node price difference multiplied by shifted load. Scope: Hub-based virtual-link market for a flexible consumer offering alternative delivery nodes.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e024"]},{"constraint_id":"v141-c-R012-C002","kind":"mathematical","role":"core","statement":"The flexible consumer's total profit in the hub-based virtual-link market equals the hub-load term (α^d − π_{n_h})d plus the virtual-link remuneration Σ_{n∈N_d}(π_{n_h} − π_n)δ_{n_h,n}, and the source states the equivalent regrouping (α^d − π_{n_h})(d − Σ_{n∈N_d}δ_{n_h,n}) + Σ_{n∈N_d}(α^d − π_n)δ_{n_h,n}.","expression":"(\\alpha^d-\\pi_{n_h})d+\\sum_{n\\in N_d}(\\pi_{n_h}-\\pi_n)\\delta_{n_h,n}=(\\alpha^d-\\pi_{n_h})\\left(d-\\sum_{n\\in N_d}\\delta_{n_h,n}\\right)+\\sum_{n\\in N_d}(\\alpha^d-\\pi_n)\\delta_{n_h,n}","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R012-x-d","v141-c-R012-x-delta"],"parameter_refs":["v141-c-R012-theta-alpha-d","v141-c-R012-theta-pi"],"evidence_ids":["v141-b-g02-e024"]}],"pi":[{"evidence_id":"v141-b-g02-e024","location":{"location_id":"src-1c03246cb9-p07-c1r4__v141-a-M03-pricing","page":7,"printed_page":null,"section":"2.4 Basic formulation with virtual links","anchor_text":"∑ 𝑑− 𝛿𝑛ℎ,𝑛≥0 (2.25d) a 𝑛∈𝑑 ce 𝑓𝑙+ −𝑓𝑙−= 𝐵𝑙(𝜃snd(𝑙) −𝜃rec(𝑙)), 𝑙∈ (2.25e) pr to 𝑝∈𝑝, 𝜃∈𝜃 (2.25f) ","equation_id":"2.26","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"The Lagrange function (2.24) reveals that virtual links are a service offered by the consumer. The market remunerates the consumer for the provision of this service via the profit \\sum_{n\\in N_d}(\\pi_{n_h}-\\pi_n)\\delta_{n_h,n}. This highlights that load-shifting is incentivized whenever there is a nodal price \\pi_n that is lower than the price at the hub node \\pi_{n_h}. This is analogous to how transmission is remunerated (based on nodal price differences). The market also charges the consumer via the profit (\\alpha^d-\\pi_{n_h})d; consequently, the flexible consumer acts as a prosumer and has total profit: (\\alpha^d-\\pi_{n_h})d+\\sum_{n\\in N_d}(\\pi_{n_h}-\\pi_n)\\delta_{n_h,n}=(\\alpha^d-\\pi_{n_h})\\left(d-\\sum_{n\\in N_d}\\delta_{n_h,n}\\right)+\\sum_{n\\in N_d}(\\alpha^d-\\pi_n)\\delta_{n_h,n} (2.26)."},{"evidence_id":"v141-b-g02-e019","location":{"location_id":"src-1c03246cb9-p06-c2r3__v141-a-M03-bidding","page":6,"printed_page":null,"section":"2.4 Basic formulation with virtual links","anchor_text":"2.4. Basic formulation with virtual links b) We have seen that there is a natural incentive for flex","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Suppose the flexible consumer submits a bid for requested load \\bar d at a hub (reference) node n_h\\in N with bid price \\alpha^d and offers at set of alternate nodes N_d\\subseteq N such that n_h\\in N_d. We use \\delta_{n_h,n}\\in R_+ to denote the amount of load that is shifted from the hub node n_h to the alternate node n\\in N_d; we refer to the load-shifting pathway as a virtual link."},{"evidence_id":"v141-b-g02-e020","location":{"location_id":"src-1c03246cb9-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":"2.4 Basic formulation with virtual links","anchor_text":"∑ ∑ min 𝛼𝑝𝑖𝑝𝑖+ 𝛼𝑓𝑘𝑓𝑘−𝛼𝑑𝑑 (2.23a) b) 𝑑,𝑝,𝑓,𝜃,𝛿 𝑖∈ 𝑘∈ ∑ ∑ s.t. 𝑓𝑘+ 𝑝𝑖 𝑘∈rec𝑛 𝑖∈𝑛 a) 𝑛= 𝑛ℎ ⎧ 𝑑−∑ 𝑗∈","equation_id":"2.23","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"This leads to the following clearing formulation: min_{d,p,f,\\theta,\\delta}\\sum_{i\\in S}\\alpha^{p}_{i}p_i+\\sum_{k\\in K}\\alpha^{f}_{k}f_k-\\alpha^d d (2.23a) s.t. \\sum_{k\\in K^{rec}_n}f_k+\\sum_{i\\in S_n}p_i=\\sum_{k\\in K^{snd}_n}f_k+\\begin{cases}d-\\sum_{j\\in N_d}\\delta_{n_h,j}, & n=n_h\\\\ \\delta_{n_h,n}, & n\\in N_d\\setminus\\{n_h\\}\\\\ 0, & n\\in N\\setminus N_d\\end{cases} (\\pi_n) (2.23b); 0\\le d\\le\\bar d (2.23c); \\delta_{n_h,n}\\ge0, n\\in N_d\\setminus\\{n_h\\} (2.23d); d-\\sum_{n\\in N_d}\\delta_{n_h,n}\\ge0 (2.23e); f_{l^+}-f_{l^-}=B_l(\\theta_{snd(l)}-\\theta_{rec(l)}), l\\in L (2.23f); p\\in C_p, \\theta\\in C_\\theta (2.23g)."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M03-pricing","v141-a-M03-settlement"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e024","quote":"The market remunerates the consumer for the provision of this service via the profit \\sum_{n\\in N_d}(\\pi_{n_h}-\\pi_n)\\delta_{n_h,n}."},{"evidence_id":"v141-b-g02-e024","quote":"The market also charges the consumer via the profit (\\alpha^d-\\pi_{n_h})d"}]],"C2_formalization":{"graph_sha256":"5ae82cdaff55dba9034885b5583a4187f9a447c4b0382f390eed5fe1efbc56e0","applicability":"formalized","reason":"Evidence v141-b-g02-e024 gives an explicit source equation (2.26) for the flexible consumer's total profit in the hub-based virtual-link market, combining the hub-load term with virtual-link remuneration by hub-minus-alternative-node price differences. This directly supports a formal settlement.payment expression. The B evidence remains unreviewed and is not claimed to have passed independent source audit.","bindings":[{"object_id":"v141-c-R012-C001","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"C001 is the frozen procedural summary of the settlement.payment relation for the hub-based virtual-link market; no graph edge exists in the frozen rule."},{"object_id":"v141-c-R012-C002","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The source equation (2.26) in v141-b-g02-e024 expresses the consumer's total profit/remuneration in the hub-based virtual-link market, directly formalizing the settlement.payment node."},{"object_id":"v141-c-R012-x-d","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The cleared hub load d is the quantity multiplied by the hub-price term in the settlement expression from v141-b-g02-e024; v141-b-g02-e020 defines its clearing domain 0 ≤ d ≤ \\bar d."},{"object_id":"v141-c-R012-x-delta","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The virtual shift δ_{n_h,n} is the quantity multiplied by the hub-minus-alternative price difference in the remuneration term from v141-b-g02-e024; v141-b-g02-e019 and v141-b-g02-e020 define it as nonnegative."},{"object_id":"v141-c-R012-theta-alpha-d","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The bid price \\alpha^d appears in the consumer's hub-load profit term in v141-b-g02-e024 and is defined in v141-b-g02-e019."},{"object_id":"v141-c-R012-theta-pi","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The nodal prices \\pi_{n_h} and \\pi_n are the settlement price inputs in the remuneration and charge terms stated in v141-b-g02-e024; v141-b-g02-e020 identifies π_n as the nodal-balance dual price."},{"object_id":"v141-c-R012-theta-dbar","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The requested-load cap \\bar d bounds the cleared hub load d in v141-b-g02-e020, which scopes the charge quantity in the payment expression from v141-b-g02-e024."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"2bb4946840b98c02ecd63b5e6522963c23cddfab3e532ecddeaf6a069ec9d08c","delivery_payload_sha256":"5e0fee5aea5809669c70f3216d835e1e684f1f10df813bccc1129c5f06e8ad58","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.2.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"5ae82cdaff55dba9034885b5583a4187f9a447c4b0382f390eed5fe1efbc56e0","scientific_correctness_verified":false}},"quarantined_references":[]}});
